import {Config, Field} from 'alinea'
import {createCMS} from 'alinea/server'

export const Page = Config.document('Page', {
  fields: {
    body: Field.text('Body', {multiline: true})
  }
})

export const cms = createCMS({
  schema: {Page},
  workspaces: {
    main: Config.workspace('Example', {
      source: 'content',
      mediaDir: 'public/media',
      roots: {
        pages: Config.root('Pages', {contains: ['Page']}),
        media: Config.media()
      }
    })
  },
  baseUrl: {
    development: 'http://localhost:4321',
    production: 'https://example.com'
  },
  handlerUrl: '/api/cms',
  adminPath: '/admin',
  preview: true
})

import {createMiddleware} from 'alinea/astro'
import {cms} from './cms'

export const onRequest = createMiddleware(cms)

import {sequence} from 'astro:middleware'
import {createMiddleware} from 'alinea/astro'
import {cms} from './cms'
import {auth} from './auth'

const alinea = createMiddleware({
  cms,
  previews: {widget: true},
  afterCommit(context) {
    // Purge caches here
  }
})

export const onRequest = sequence(alinea, auth)

