import {Query} from 'alinea'
import {cms, Page} from '../cms'

const pages = await cms.find({
  type: Page,
  select: {title: Query.title, url: Query.url}
})
---

<nav>
  {pages.map(page => <a href={page.url}>{page.title}</a>)}
</nav>

{
  "scripts": {
    "dev": "alinea dev -- astro dev",
