import {Query} from 'alinea'
import {cms, Page} from '../cms'

export async function getStaticPaths() {
  const urls = await cms.find({type: Page, select: Query.url})
  return urls.map(url => ({params: {slug: url.slice(1)}}))
}

const page = await cms.first({type: Page, url: `/${Astro.params.slug}`})
